// ===== MavlinkDirectServer Wrapper =====

struct mavsdk_mavlink_direct_server_wrapper {
    std::shared_ptr<mavsdk::MavlinkDirectServer> cpp_plugin;
};

mavsdk_mavlink_direct_server_t
mavsdk_mavlink_direct_server_create(mavsdk_server_component_t server_component) {
    if (server_component == nullptr) {
        return nullptr;
    }

    auto wrapper = new mavsdk_mavlink_direct_server_wrapper();
    auto server_component_ptr = reinterpret_cast<std::shared_ptr<mavsdk::ServerComponent>*>(server_component);
    wrapper->cpp_plugin = std::make_shared<mavsdk::MavlinkDirectServer>(*server_component_ptr);

    return reinterpret_cast<mavsdk_mavlink_direct_server_t>(wrapper);
}

void mavsdk_mavlink_direct_server_destroy(mavsdk_mavlink_direct_server_t mavlink_direct_server) {
    if (mavlink_direct_server == nullptr) {
        return;
    }

    // Releasing the handles is the caller's job. Dropping the plugin marks every
    // subscription of it dead anyway, so nothing can fire into it after this.
    delete reinterpret_cast<mavsdk_mavlink_direct_server_wrapper*>(mavlink_direct_server);
}

// ===== Method Implementations =====


// SendMessage sync
mavsdk_mavlink_direct_server_result_t
mavsdk_mavlink_direct_server_send_message(
    mavsdk_mavlink_direct_server_t mavlink_direct_server,
    mavsdk_mavlink_direct_server_mavlink_message_t message)
{
    auto wrapper = reinterpret_cast<mavsdk_mavlink_direct_server_wrapper*>(mavlink_direct_server);

    auto ret_value = wrapper->cpp_plugin->send_message(        translate_mavlink_message_from_c(message));

    return translate_result(ret_value);
}

// Message async
mavsdk_mavlink_direct_server_message_handle_t mavsdk_mavlink_direct_server_subscribe_message(
    mavsdk_mavlink_direct_server_t mavlink_direct_server,
    char* message_name,
    mavsdk_mavlink_direct_server_message_callback_t callback,
    void* user_data)
{
    auto wrapper = reinterpret_cast<mavsdk_mavlink_direct_server_wrapper*>(mavlink_direct_server);

    auto cpp_handle =    wrapper->cpp_plugin->subscribe_message(
        message_name,
        [callback, user_data](
            mavsdk::MavlinkDirectServer::MavlinkMessage value) {
                if (callback) {
                    callback(
                        translate_mavlink_message_to_c(value),
                        user_data);
                }
        });

    auto cpp_handle_ptr = new mavsdk::MavlinkDirectServer::MessageHandle(std::move(cpp_handle));

    return reinterpret_cast<mavsdk_mavlink_direct_server_message_handle_t>(cpp_handle_ptr);
}

void mavsdk_mavlink_direct_server_unsubscribe_message(
    mavsdk_mavlink_direct_server_t mavlink_direct_server,
    mavsdk_mavlink_direct_server_message_handle_t handle)
{
    if (mavlink_direct_server == nullptr || handle == nullptr) {
        return;
    }

    auto wrapper = reinterpret_cast<mavsdk_mavlink_direct_server_wrapper*>(mavlink_direct_server);
    auto cpp_handle = reinterpret_cast<mavsdk::MavlinkDirectServer::MessageHandle*>(handle);

    wrapper->cpp_plugin->unsubscribe_message(std::move(*cpp_handle));
    delete cpp_handle;
}



// LoadCustomXml sync
mavsdk_mavlink_direct_server_result_t
mavsdk_mavlink_direct_server_load_custom_xml(
    mavsdk_mavlink_direct_server_t mavlink_direct_server,
    char* xml_content)
{
    auto wrapper = reinterpret_cast<mavsdk_mavlink_direct_server_wrapper*>(mavlink_direct_server);

    auto ret_value = wrapper->cpp_plugin->load_custom_xml(        xml_content);

    return translate_result(ret_value);
}
